#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', '..', '..', '..', '..');
const IN_MD = path.join(ROOT, '001 banco de retos de benevolencia.md');
const OUT_JSON = path.join(__dirname, '..', 'data', 'benevolencia-challenges.json');
const OUT_JS = path.join(__dirname, '..', 'data', 'benevolencia-challenges.js');

const CHALLENGE_RE = /^- \*\*Challenge (\d+) \[([^\]]+)\]\*\*: (.+)$/;

function skillLevelForChallenge(globalNumber) {
    if (globalNumber <= 20) return 1;
    if (globalNumber <= 40) return 2;
    return 3;
}

function bankLevelForChallenge(globalNumber) {
    return skillLevelForChallenge(globalNumber);
}

function numberWithinBank(globalNumber) {
    const bank = bankLevelForChallenge(globalNumber);
    return globalNumber - (bank - 1) * 20;
}

function parseMarkdown(content) {
    const challenges = [];
    const lines = content.split(/\r?\n/);

    lines.forEach(line => {
        const match = line.trim().match(CHALLENGE_RE);
        if (!match) return;

        const globalNumber = Number(match[1]);
        const title = match[2].trim();
        const body = match[3].trim();
        const bankLevel = bankLevelForChallenge(globalNumber);
        const number = numberWithinBank(globalNumber);
        const skillLevel = skillLevelForChallenge(globalNumber);

        challenges.push({
            bankLevel,
            number,
            globalNumber,
            title,
            text: `[${title}] ${body}`,
            skillLevel
        });
    });

    return challenges;
}

if (!fs.existsSync(IN_MD)) {
    console.error(`Missing markdown file: ${IN_MD}`);
    process.exit(1);
}

const markdown = fs.readFileSync(IN_MD, 'utf8');
const challenges = parseMarkdown(markdown);

if (challenges.length !== 60) {
    console.error(`Expected 60 challenges, parsed ${challenges.length}`);
    process.exit(1);
}

fs.writeFileSync(OUT_JSON, JSON.stringify(challenges, null, 2), 'utf8');
fs.writeFileSync(
    OUT_JS,
    `/* Auto-generated by dev/scripts/generate-benevolencia-data.js */\nconst BENEVOLENCIA_CHALLENGES = ${JSON.stringify(challenges, null, 2)};\n\nmodule.exports = { BENEVOLENCIA_CHALLENGES };\n`,
    'utf8'
);

console.log(`Generated ${challenges.length} benevolencia challenges`);
